export class MissingLocaleDataError extends Error {
  constructor(locale: string) {
    super(`No CLDR formatting data is loaded for locale '${locale}'.`);
  }
}

export function dataFor(locale: string): CldrLocaleData {
  const found = CLDR_DATA[locale];
  if (found === undefined) {
    throw new MissingLocaleDataError(locale);
  }
  return found;
}

// ---------------------------------------------------------------------------
// Plural selection.
// ---------------------------------------------------------------------------

function operandsOf(n: number): PluralOperands {
  const absN = Math.abs(n);
  if (Number.isInteger(absN)) {
    return { n: absN, i: absN, v: 0, f: 0 };
  }
  const [intText, fracText] = absN.toString().split('.');
  return { n: absN, i: Number(intText), v: fracText.length, f: Number(fracText) };
}

function operandValue(name: string, operands: PluralOperands): number {
  switch (name) {
    case 'n':
      return operands.n;
    case 'i':
      return operands.i;
    case 'v':
      return operands.v;
    case 'f':
      return operands.f;
    default:
      throw new Error(`Plural relation names operand '${name}', but only n/i/v/f are supported.`);
  }
}

function rangeMatches(value: number, rangeText: string): boolean {
  const trimmed = rangeText.trim();
  if (trimmed.includes('..')) {
    const [low, high] = trimmed.split('..');
    return value >= Number(low) && value <= Number(high);
  }
  return value === Number(trimmed);
}

function comparisonMatches(comparison: string, operands: PluralOperands): boolean {
  const negate = comparison.includes('!=');
  const [left, right] = comparison.split(negate ? '!=' : '=');
  if (right === undefined) {
    throw new Error(`Plural relation comparison '${comparison}' has neither '=' nor '!='.`);
  }
  const trimmedLeft = left.trim();
  let value: number;
  if (trimmedLeft.includes('%')) {
    const [operandName, modulusText] = trimmedLeft.split('%');
    value = operandValue(operandName.trim(), operands) % Number(modulusText.trim());
  } else {
    value = operandValue(trimmedLeft, operands);
  }
  const matched = right.split(',').some((part) => rangeMatches(value, part));
  return matched !== negate;
}

function evaluatePluralRelation(relation: string, operands: PluralOperands): boolean {
  return relation
    .split(/\s+or\s+/)
    .some((conjunction) =>
      conjunction.split(/\s+and\s+/).every((comparison) => comparisonMatches(comparison.trim(), operands)),
    );
}

const PLURAL_CATEGORY_ORDER: readonly PluralCategory[] = ['zero', 'one', 'two', 'few', 'many'];

export function pluralCategory(n: number, locale: string): PluralCategory {
  const rules = dataFor(locale).pluralRules;
  const operands = operandsOf(n);
  for (const category of PLURAL_CATEGORY_ORDER) {
    const relation = rules[category];
    if (relation !== undefined && evaluatePluralRelation(relation, operands)) {
      return category;
    }
  }
  return 'other';
}

// ---------------------------------------------------------------------------
// Number pattern parsing -- one closed CLDR pattern grammar
// (`#`/`0`/`,`/`.`/literal prefix-suffix text), applied to the decimal,
// currency and percent patterns alike.
// ---------------------------------------------------------------------------

interface ParsedNumberPattern {
  readonly prefix: string;
  readonly suffix: string;
  readonly groupSize: number;
  readonly grouped: boolean;
  readonly minFractionDigits: number;
  readonly maxFractionDigits: number;
}

function parseNumberPattern(pattern: string): ParsedNumberPattern {
  const digitIndexes: number[] = [];
  for (let index = 0; index < pattern.length; index += 1) {
    if (pattern[index] === '#' || pattern[index] === '0') {
      digitIndexes.push(index);
    }
  }
  const first = digitIndexes[0];
  const last = digitIndexes[digitIndexes.length - 1];
  const prefix = pattern.slice(0, first);
  const suffix = pattern.slice(last + 1);
  const numeric = pattern.slice(first, last + 1);
  const dotIndex = numeric.indexOf('.');
  const intPart = dotIndex === -1 ? numeric : numeric.slice(0, dotIndex);
  const fracPart = dotIndex === -1 ? '' : numeric.slice(dotIndex + 1);
  const commaIndex = intPart.lastIndexOf(',');
  const groupSize = commaIndex === -1 ? 0 : intPart.length - commaIndex - 1;
  return {
    prefix,
    suffix,
    groupSize,
    grouped: commaIndex !== -1,
    minFractionDigits: fracPart.split('').filter((ch) => ch === '0').length,
    maxFractionDigits: fracPart.length,
  };
}

function groupInteger(digits: string, groupSize: number): string {
  if (groupSize <= 0) {
    return digits;
  }
  const groups: string[] = [];
  let end = digits.length;
  while (end > 0) {
    const start = Math.max(0, end - groupSize);
    groups.unshift(digits.slice(start, end));
    end = start;
  }
  return groups.join(',');
}

function formatWithPattern(value: number, pattern: string, symbols: CldrNumberSymbols): string {
  const parsed = parseNumberPattern(pattern);
  const negative = value < 0;
  const magnitude = Math.abs(value);
  const fixed = magnitude.toFixed(parsed.maxFractionDigits);
  const [intText, fracTextRaw] = fixed.split('.');
  let fracText = fracTextRaw ?? '';
  while (fracText.length > parsed.minFractionDigits && fracText.endsWith('0')) {
    fracText = fracText.slice(0, -1);
  }
  const groupedInt = groupInteger(intText, parsed.grouped ? parsed.groupSize : 0)
    .split(',')
    .join(symbols.group);
  const body = fracText.length > 0 ? `${groupedInt}${symbols.decimal}${fracText}` : groupedInt;
  const sign = negative ? symbols.minusSign : '';
  return `${sign}${parsed.prefix}${body}${parsed.suffix}`;
}

// ---------------------------------------------------------------------------
// Date/time pattern token substitution.
// ---------------------------------------------------------------------------

const DATE_TIME_FIELD_LETTERS = new Set(['y', 'M', 'd', 'H', 'h', 'm', 's', 'a']);

function tokenizePattern(pattern: string): string[] {
  const tokens: string[] = [];
  let index = 0;
  while (index < pattern.length) {
    const char = pattern[index];
    if (DATE_TIME_FIELD_LETTERS.has(char)) {
      let end = index;
      while (end < pattern.length && pattern[end] === char) {
        end += 1;
      }
      tokens.push(pattern.slice(index, end));
      index = end;
    } else {
      tokens.push(char);
      index += 1;
    }
  }
  return tokens;
}

function pad2(value: number): string {
  return value < 10 ? `0${value}` : String(value);
}

function applyDateTimePattern(value: Date, pattern: string, data: CldrLocaleData): string {
  const hour24 = value.getHours();
  const hour12 = hour24 % 12 || 12;
  const dayPeriod: 'am' | 'pm' = hour24 < 12 ? 'am' : 'pm';
  return tokenizePattern(pattern)
    .map((token) => {
      const field = token[0];
      const width = token.length;
      switch (field) {
        case 'y':
          return width === 2 ? pad2(value.getFullYear() % 100) : String(value.getFullYear());
        case 'M':
          if (width >= 4) return data.monthNamesWide[value.getMonth()];
          if (width === 3) return data.monthNamesShort[value.getMonth()];
          return width === 2 ? pad2(value.getMonth() + 1) : String(value.getMonth() + 1);
        case 'd':
          return width === 2 ? pad2(value.getDate()) : String(value.getDate());
        case 'H':
          return width === 2 ? pad2(hour24) : String(hour24);
        case 'h':
          return width === 2 ? pad2(hour12) : String(hour12);
        case 'm':
          return width === 2 ? pad2(value.getMinutes()) : String(value.getMinutes());
        case 's':
          return width === 2 ? pad2(value.getSeconds()) : String(value.getSeconds());
        case 'a':
          return data.dayPeriods[dayPeriod];
        default:
          return token;
      }
    })
    .join('');
}

// ---------------------------------------------------------------------------
// Relative time -- plural-category-dispatched templates from the extract's
// own `relativeTime` unit tables, never a hardcoded singular/plural binary.
// ---------------------------------------------------------------------------

export const RELATIVE_TIME_THRESHOLDS: readonly [number, string, number][] = [
  [60, 'second', 1],
  [3600, 'minute', 60],
  [86400, 'hour', 3600],
  [604800, 'day', 86400],
  [2592000, 'week', 604800],
  [31536000, 'month', 2592000],
  [Number.POSITIVE_INFINITY, 'year', 31536000],
];

// ---------------------------------------------------------------------------
// Public, locale-parameterized Fmt.* logic. `format.ts`'s `FormatService`
// reads the session locale and delegates to these; the CLDR fixture test
// calls these directly, one locale at a time, with no session/DI object.
// ---------------------------------------------------------------------------

export function formatNumber(value: number, locale: string): string {
  const data = dataFor(locale);
  return formatWithPattern(value, data.numberPatterns.decimal, data.numberSymbols);
}

export function formatMoney(value: number, locale: string): string {
  const data = dataFor(locale);
  const pattern = data.numberPatterns.currency.split('¤').join(data.currency.symbol);
  return formatWithPattern(value, pattern, data.numberSymbols);
}

export function formatPercent(value: number, locale: string): string {
  const data = dataFor(locale);
  return formatWithPattern(value * 100, data.numberPatterns.percent, data.numberSymbols);
}

export function formatDate(value: Date, locale: string): string {
  const data = dataFor(locale);
  return applyDateTimePattern(value, data.datePatterns.short, data);
}

export function formatTime(value: Date, locale: string): string {
  const data = dataFor(locale);
  return applyDateTimePattern(value, data.timePatterns.short, data);
}

export function formatDateTime(value: Date, locale: string): string {
  return `${formatDate(value, locale)} ${formatTime(value, locale)}`;
}

/** Pure, wall-clock-free relative-time rendering: the unit/amount are
 * already computed (by `FormatService.relative` from an elapsed `Date`
 * delta, or directly by a test) -- this function only picks the
 * plural-dispatched template and substitutes `{0}`. */
export function formatRelativeAmount(unit: string, amount: number, locale: string): string {
  const data = dataFor(locale);
  const forms = data.relativeTime[unit];
  if (forms === undefined) {
    throw new Error(`No relative-time forms for unit '${unit}' in locale '${locale}'.`);
  }
  const category = pluralCategory(amount, locale);
  const template = forms[category] ?? forms['other'];
  return template.replace('{0}', String(amount));
}

/** The (unit, amount) an elapsed `Date` delta resolves to, per
 * `RELATIVE_TIME_THRESHOLDS` -- factored out of `FormatService.relative` so
 * it, too, is independently callable. */
export function relativeUnitAndAmount(absSeconds: number): readonly [string, number] {
  const [, unit, unitSeconds] =
    RELATIVE_TIME_THRESHOLDS.find(([limit]) => absSeconds < limit) ??
    RELATIVE_TIME_THRESHOLDS[RELATIVE_TIME_THRESHOLDS.length - 1];
  return [unit, Math.max(1, Math.round(absSeconds / unitSeconds))];
}
